    {
      "id": "7331cccb-8750-4c76-93de-c96ffdc75293",
      "name": "Code in JavaScript2",
      "type": "n8n-nodes-base.code",
      "position": [
        -48,
        1296
      ],
      "parameters": {
        "jsCode": "// n8n Code Node\nconst items = $input.all();\n\n// Step 1: Group items by ID\nconst groups = {};\nfor (const item of items) {\n  const id = item.json.ID;\n  if (!groups[id]) groups[id] = [];\n  groups[id].push(item);\n}\n\nconst uniqueIds = Object.keys(groups);\n\n// Step 2: If all items share the same ID, return all\nif (uniqueIds.length === 1) {\n  return items;\n}\n\n// Step 3: Find the minimum group size\nconst minCount = Math.min(...uniqueIds.map(id => groups[id].length));\n\n// Step 4: Return only the group(s) with the minimum entry count\nconst result = [];\nfor (const id of uniqueIds) {\n  if (groups[id].length === minCount) {\n    result.push(...groups[id]);\n  }\n}\n\nreturn result;"
      },
      "typeVersion": 2
    },
